const results = [];

for (const item of $input.all()) {
  const d = item.json;

  const errors = [];

  if (!d.invoice_id) errors.push("Missing Invoice ID");
  if (!d.invoice_date) errors.push("Missing Invoice Date");
  if (!d.due_date) errors.push("Missing Due Date");
  if (!d.total_amount || Number(d.total_amount) <= 0) {
    errors.push("Invalid Total Amount");
  }

  if (
    d.invoice_date &&
    d.due_date &&
    new Date(d.due_date) < new Date(d.invoice_date)
  ) {
    errors.push("Due Date Before Invoice Date");
  }

  results.push({
    json: {
      ...d,
      validation_status: errors.length === 0 ? "Valid" : "Invalid",
      validation_errors: errors.join(", ")
    }
  });
}

return results;

const items = $input.all();

const invoiceCounts = {};

for (const item of items) {
  const invoiceId = item.json.invoice_id;

  invoiceCounts[invoiceId] = (invoiceCounts[invoiceId] || 0) + 1;
}

return items.map(item => {
  const invoiceId = item.json.invoice_id;
  const count = invoiceCounts[invoiceId];

  return {
    json: {
      ...item.json,
      duplicate_status: count > 1 ? "Duplicate" : "Unique",
      duplicate_count: count
    }
  };
});

const today = new Date();

return $input.all().map(item => {
  const d = item.json;

  const dueDate = new Date(d.due_date);
  const totalAmount = Number(d.total_amount || 0);
  const paidAmount = Number(d.paid_amount || 0);
  const balanceDue = Number(d.balance_due || 0);

  let payment_status = d.payment_status || "Unknown";
  let due_status = "Not Due";

  if (balanceDue <= 0) {
    due_status = "Paid";
  } else if (dueDate < today) {
    due_status = "Overdue";
  } else {
    due_status = "Due";
  }

  return {
    json: {
      ...d,
      calculated_balance_due: totalAmount - paidAmount,
      payment_status,
      due_status
    }
  };
});

return $input.all().map(item => {
  const d = item.json;

  const invoiceAmount = Number(d.total_amount || 0);
  const transactionAmount = Number(d.amount || 0);

  const difference = invoiceAmount - transactionAmount;

  let reconciliation_status;

  if (difference === 0) {
    reconciliation_status = "Fully Matched";
  } else if (transactionAmount === 0) {
    reconciliation_status = "No Payment";
  } else if (difference > 0) {
    reconciliation_status = "Underpaid";
  } else {
    reconciliation_status = "Overpaid";
  }

  return {
    json: {
      ...d,
      invoice_amount: invoiceAmount,
      transaction_amount: transactionAmount,
      amount_difference: difference,
      reconciliation_status
    }
  };
});

const items = $input.all();
const grouped = {};

for (const item of items) {
  const d = item.json;
  const invoiceId = d.invoice_id;

  if (!invoiceId) continue;

  if (!grouped[invoiceId]) {
    grouped[invoiceId] = {
      invoice_id: invoiceId,
      transaction_count: 0,
      valid_payment_count: 0,
      valid_payment_amount: 0
    };
  }

  const amount = Math.abs(Number(d.amount || 0));
  const type = String(d.type || "").trim().toLowerCase();
  const status = String(d.transaction_status || "").trim().toLowerCase();
  const description = String(d.description || "").trim().toLowerCase();

  grouped[invoiceId].transaction_count += 1;

  const validPayment =
    type === "credit" &&
    status === "completed" &&
    (
      description === "invoice payment" ||
      description === "partial payment" ||
      description === "vendor settlement"
    );

  if (validPayment) {
    grouped[invoiceId].valid_payment_count += 1;
    grouped[invoiceId].valid_payment_amount += amount;
  }
}

return Object.values(grouped).map(d => ({
  json: {
    invoice_id: d.invoice_id,
    transaction_count: d.transaction_count,
    valid_payment_count: d.valid_payment_count,
    valid_payment_amount: Number(
      d.valid_payment_amount.toFixed(2)
    )
  }
}));

return $input.all().map(item => {
  const d = item.json;

  const invoiceAmount = Number(d.total_amount || 0);
  const paymentAmount = Number(d.valid_payment_amount || 0);

  const difference = Number(
    (invoiceAmount - paymentAmount).toFixed(2)
  );

  let reconciliationStatus;

  if (paymentAmount === 0) {
    reconciliationStatus = "No Payment";
  } else if (Math.abs(difference) < 0.01) {
    reconciliationStatus = "Fully Matched";
  } else if (difference > 0) {
    reconciliationStatus = "Underpaid";
  } else {
    reconciliationStatus = "Overpaid";
  }

  return {
    json: {
      ...d,
      invoice_amount: invoiceAmount,
      transaction_amount: paymentAmount,
      amount_difference: difference,
      reconciliation_status: reconciliationStatus
    }
  };
});

return $input.all().map(item => {
  const d = item.json;

  const exceptions = [];

  if (d.validation_status === "Invalid") {
    exceptions.push("Invalid Invoice");
  }

  if (d.duplicate_status === "Duplicate") {
    exceptions.push("Duplicate Invoice");
  }

  if (d.due_status === "Overdue") {
    exceptions.push("Overdue Payment");
  }

  if (
    d.reconciliation_status === "Underpaid" ||
    d.reconciliation_status === "Overpaid" ||
    d.reconciliation_status === "No Payment"
  ) {
    exceptions.push(d.reconciliation_status);
  }

  return {
    json: {
      ...d,
      exception_status: exceptions.length > 0 ? "Exception" : "No Exception",
      exception_type: exceptions.length > 0
        ? exceptions.join(", ")
        : "None"
    }
  };
});

const items = $input.all();

let totalInvoices = items.length;
let totalInvoiceAmount = 0;
let totalPaidAmount = 0;
let totalBalanceDue = 0;
let overdueInvoices = 0;
let exceptionInvoices = 0;
let duplicateInvoices = 0;
let validInvoices = 0;

for (const item of items) {
  const d = item.json;

  totalInvoiceAmount += Number(d.total_amount || 0);
  totalPaidAmount += Number(d.valid_payment_amount || 0);
  totalBalanceDue += Number(d.balance_due || 0);

  if (d.due_status === "Overdue") {
    overdueInvoices++;
  }

  if (d.exception_status === "Exception") {
    exceptionInvoices++;
  }

  if (d.duplicate_status === "Duplicate") {
    duplicateInvoices++;
  }

  if (d.validation_status === "Valid") {
    validInvoices++;
  }
}

return [
  {
    json: {
      total_invoices: totalInvoices,
      total_invoice_amount: Number(totalInvoiceAmount.toFixed(2)),
      total_paid_amount: Number(totalPaidAmount.toFixed(2)),
      total_balance_due: Number(totalBalanceDue.toFixed(2)),
      overdue_invoices: overdueInvoices,
      exception_invoices: exceptionInvoices,
      duplicate_invoices: duplicateInvoices,
      valid_invoices: validInvoices
    }
  }
];

const d = $input.first().json;

return [
  {
    json: {
      report_name: "Invoice Processing & Accounts Analytics Report",
      total_invoices: d.total_invoices,
      total_invoice_amount: d.total_invoice_amount,
      total_paid_amount: d.total_paid_amount,
      total_balance_due: d.total_balance_due,
      overdue_invoices: d.overdue_invoices,
      exception_invoices: d.exception_invoices,
      duplicate_invoices: d.duplicate_invoices,
      valid_invoices: d.valid_invoices,
      generated_at: new Date().toISOString()
    }
  }
];
